// Shared server-side helpers for Cloudflare Pages Functions. No secrets are stored here.
const TOKEN_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_~!@$*';
const DIGITS = '0123456789';

function randomChars(alphabet, length) {
  // Rejection sampling avoids modulo bias in crypto-generated bytes.
  let result = '';
  const ceiling = 256 - (256 % alphabet.length);
  while (result.length < length) {
    const bytes = crypto.getRandomValues(new Uint8Array(length * 2));
    for (const byte of bytes) {
      if (byte < ceiling) result += alphabet[byte % alphabet.length];
      if (result.length === length) break;
    }
  }
  return result;
}

export function randomId() { return randomChars('123456789', 1) + randomChars(DIGITS, 9); }
export function randomToken() { return randomChars(TOKEN_CHARS, 20); }

export function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer'
  } });
}

export async function unusedId(kv, rank) {
  for (let attempt = 0; attempt < 5; attempt++) {
    const id = randomId();
    if (await kv.get(`${rank}:${id}`) === null) return id;
  }
  throw new Error('Could not allocate a record ID');
}

export function reviewURL(request, rank, id, token) {
  const origin = new URL(request.url).origin;
  return `${origin}/record/#${rank}/${id}?token=${encodeURIComponent(token)}`;
}

export async function sendWebhook(url, record, reviewLink) {
  const response = await fetch(url, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      allowed_mentions: { parse: [] },
      embeds: [{
        title: record.isTest ? 'SEDL system test' : 'New SEDL record submission',
        color: 12971384,
        fields: [
          { name: 'Player', value: record.player, inline: true },
          { name: 'Level', value: `#${record.rank} ${record.levelName}`, inline: true },
          { name: 'Speed', value: record.speed, inline: true },
          { name: 'Video', value: record.video || 'Not provided' },
          { name: 'Raw footage', value: record.rawFootage || 'Not provided' },
          { name: 'Private staff review', value: `[Open private review](${reviewLink})` }
        ],
        timestamp: record.submittedAt
      }]
    })
  });
  if (!response.ok) throw new Error(`Discord webhook returned ${response.status}`);
}

export function safeHttpURL(value) {
  if (typeof value !== 'string' || value.length > 500) return '';
  try {
    const url = new URL(value.trim());
    if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return '';
    return url.href;
  } catch (_) { return ''; }
}

export function youtubeURL(value) {
  const safe = safeHttpURL(value);
  if (!safe) return '';
  const url = new URL(safe);
  const host = url.hostname.toLowerCase();
  const id = host === 'youtu.be' ? url.pathname.split('/')[1] :
    ['youtube.com', 'www.youtube.com', 'm.youtube.com'].includes(host) ?
      (url.searchParams.get('v') || (/^\/(?:shorts|embed|live)\/([^/]+)/.exec(url.pathname) || [])[1]) : '';
  return /^[A-Za-z0-9_-]{11}$/.test(id || '') ? safe : '';
}

export async function readJSON(request, limit = 8192) {
  if (!request.body) throw new Error('Missing body');
  const reader = request.body.getReader();
  const chunks = []; let size = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > limit) { await reader.cancel(); throw new Error('Body too large'); }
    chunks.push(value);
  }
  const bytes = new Uint8Array(size); let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  return JSON.parse(new TextDecoder().decode(bytes));
}
